#include <type_traits>
#include <string>

// A template function demonstrating type transformations
template<typename T>
void transform_and_use() {
  // 1. Remove reference and const qualifiers to get the base type
  using BaseType = typename std::remove_cv<typename std::remove_reference<T>::type>::type;

  // 2. C++14 alias templates make this much cleaner
  using BaseType_t = std::remove_cv_t<std::remove_reference_t<T>>;

  // 3. Create a new type: a pointer to a const version of the base type
  using ConstPointerType = std::add_pointer_t<std::add_const_t<BaseType_t>>;

  ConstPointerType ptr = nullptr;
}

void run_example() {
  // T will be deduced as const std::string&
  // BaseType_t will be std::string
  // ConstPointerType will be const std::string*
  transform_and_use<const std::string&>();
}
